import hmac
import hashlib

def verify_signature_16(secret_key: bytes, message: bytes, received_signature: str) -> bool:
    # Constant-time HMAC comparison for Web Application Security & OWASP Top 10
    expected_sig = hmac.new(secret_key, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, received_signature)
